import 'package:ckcoreui/ckcoreui.dart';
import 'package:flutter/material.dart';

void main() {
  runApp(const MyApp());
}

class MyApp extends StatelessWidget {
  const MyApp({super.key});

  @override
  Widget build(BuildContext context) {
    return CKApp(
      brand: ckcoreBrand.skyGo, // choose your brand
      title: 'My App',
      home: const HomePage(),
    );
  }
}

themeSwitching.code:
class _MyAppState extends State<MyApp> {
  Brightness? _brightness; // null = follow the system

  @override
  Widget build(BuildContext context) {
    return CKApp(
      brand: ckcoreBrand.skyGo,
      brightness: _brightness,
      home: Scaffold(
        body: Center(
          child: CKSwitch(
            label: 'Dark mode',
            value: _brightness == Brightness.dark,
            onChanged: (dark) => setState(
              () => _brightness = dark ? Brightness.dark : Brightness.light,
            ),
          ),
        ),
      ),
    );
  }
}

brandSwitching.code:
class _MyAppState extends State<MyApp> {
  ckcoreBrand _brand = ckcoreBrand.skyGo;

  @override
  Widget build(BuildContext context) {
    return CKApp(
      brand: _brand,
      home: Scaffold(
        body: Center(
          child: DropdownButton<ckcoreBrand>(
            value: _brand,
            items: [
              for (final brand in ckcoreBrand.values)
                DropdownMenuItem(value: brand, child: Text(brand.displayName)),
            ],
            onChanged: (brand) {
              if (brand != null) setState(() => _brand = brand);
            },
          ),
        ),
      ),
    );
  }
}
